INSERT INTO roles(name) VALUES ('Super Admin'),('Admin'),('User') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO permissions(name) VALUES ('dashboard.view'),('expenses.view'),('expenses.create'),('expenses.edit'),('expenses.delete'),('categories.view'),('categories.create'),('categories.edit'),('categories.delete'),('accounts.view'),('accounts.create'),('accounts.edit'),('accounts.delete'),('budgets.view'),('budgets.create'),('budgets.edit'),('budgets.delete'),('reports.view'),('reports.export'),('users.view'),('users.create'),('users.edit'),('users.delete'),('settings.view') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO users(name,email,password_hash,status,created_at,updated_at) VALUES ('System Administrator','admin@example.com','$2y$10$/TUhoJgUOtPdbg2BqUH0ueqn1UG8/6cLhK6Hk2pjldusi5L8MHZMq','active',NOW(),NOW()) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash),status=VALUES(status),updated_at=NOW();
INSERT INTO user_roles(user_id,role_id) SELECT u.id,r.id FROM users u JOIN roles r ON r.name='Super Admin' WHERE u.email='admin@example.com' ON DUPLICATE KEY UPDATE user_id=user_id;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='Super Admin' ON DUPLICATE KEY UPDATE role_id=role_id;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','expenses.view','expenses.create','expenses.edit','expenses.delete','categories.view','categories.create','categories.edit','categories.delete','accounts.view','accounts.create','accounts.edit','accounts.delete','budgets.view','budgets.create','budgets.edit','budgets.delete','reports.view','reports.export') WHERE r.name='Admin' ON DUPLICATE KEY UPDATE role_id=role_id;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','expenses.view','expenses.create','expenses.edit','categories.view','accounts.view','budgets.view','reports.view') WHERE r.name='User' ON DUPLICATE KEY UPDATE role_id=role_id;
